script:
frappe.ui.form.on("Follow Up", {
    refresh(frm) {
        check_follow_up_status(frm);
    },

    follow_up_date(frm) {
        check_follow_up_status(frm);
    },

    status(frm) {
        check_follow_up_status(frm);
    },

    validate(frm) {
        if (frm.doc.status === "Pending" && !frm.doc.follow_up_date) {
            frappe.throw(__("Follow Up Date is required for a Pending follow-up."));
        }

        if (frm.doc.status === "Completed" && !frm.doc.notes) {
            frappe.throw(__("Please add Notes before completing the follow-up."));
        }
    }
});

function check_follow_up_status(frm) {
    if (!frm.doc.follow_up_date) {
        return;
    }

    if (frm.doc.status === "Completed") {
        return;
    }

    const today = frappe.datetime.get_today();

    if (frm.doc.follow_up_date < today) {
        frappe.msgprint({
            title: __("Overdue Follow-up"),
            message: __(
                "This follow-up is overdue. Please complete it or update the follow-up date."
            ),
            indicator: "red"
        });
    } else if (frm.doc.follow_up_date === today) {
        frappe.msgprint({
            title: __("Follow-up Due Today"),
            message: __("This follow-up is due today."),
            indicator: "orange"
        });
    }
}
